<!-- Generated by Trae Work -->
(function () {
  'use strict';

  /* ---- 从 CSS 变量读取颜色 ---- */
  var style = getComputedStyle(document.documentElement);
  var accent  = style.getPropertyValue('--accent').trim();   // #2563eb
  var accent2 = style.getPropertyValue('--accent2').trim();   // #0ea5e9
  var ink     = style.getPropertyValue('--ink').trim();       // #1a1a2e
  var muted   = style.getPropertyValue('--muted').trim();     // #6b7280
  var rule    = style.getPropertyValue('--rule').trim();      // #e2e8f0

  /* ---- 调色板（5 家企业对应 5 色） ---- */
  var PALETTE = ['#2563eb', '#0ea5e9', '#10b981', '#f59e0b', '#ef4444'];
  var COMPANIES = ['递四方(4PX)', '云途(YunExpress)', '燕文(Yanwen)', '万邑通(Winit)', '九方通逊'];

  /* ---- 公共 tooltip formatter ---- */
  function tipUnit(unit) {
    return {
      trigger: 'axis',
      axisPointer: { type: 'shadow' },
      formatter: function (params) {
        var s = params[0].axisValueLabel + '<br/>';
        params.forEach(function (p) {
          s += '<span style="display:inline-block;width:10px;height:10px;border-radius:50%;background:'
            + p.color + ';margin-right:6px;"></span>'
            + p.seriesName + ': ' + p.value + unit + '<br/>';
        });
        return s;
      }
    };
  }

  /* ============================================================
   * 1. chart-price — 分组柱状图：3 组渠道 x 5 家企业
   * ============================================================ */
  function initPriceChart() {
    var dom = document.getElementById('chart-price');
    if (!dom) return;
    var chart = echarts.init(dom);

    var categories = ['经济小包 0.5kg', '标准专线 1kg', '快速专线 1kg'];
    var data = {
      '递四方(4PX)':    [25, 60, 90],
      '云途(YunExpress)': [22, 55, 85],
      '燕文(Yanwen)':   [20, 50, 80],
      '万邑通(Winit)':  [24, 58, 88],
      '九方通逊':        [26, 62, 92]
    };

    var series = COMPANIES.map(function (name, i) {
      return {
        name: name,
        type: 'bar',
        data: data[name],
        itemStyle: { color: PALETTE[i], borderRadius: [4, 4, 0, 0] },
        barGap: '10%',
        barCategoryGap: '30%'
      };
    });

    chart.setOption({
      animation: false,
      tooltip: tipUnit(' 元'),
      legend: {
        bottom: 0,
        textStyle: { color: muted, fontFamily: 'InstrumentSans', fontSize: 12 }
      },
      grid: { left: 60, right: 30, top: 30, bottom: 60 },
      xAxis: {
        type: 'category',
        data: categories,
        axisLabel: { color: ink, fontSize: 12, fontFamily: 'InstrumentSans' },
        axisLine: { lineStyle: { color: rule } },
        axisTick: { show: false }
      },
      yAxis: {
        type: 'value',
        name: '价格（元）',
        nameTextStyle: { color: muted, fontSize: 12, fontFamily: 'InstrumentSans' },
        axisLabel: { color: muted, fontSize: 11, fontFamily: 'InstrumentSans' },
        splitLine: { lineStyle: { color: rule, type: 'dashed' } },
        axisLine: { show: false },
        axisTick: { show: false }
      },
      series: series
    });

    window.addEventListener('resize', function () { chart.resize(); });
  }

  /* ============================================================
   * 2. chart-time — 雷达图：时效维度评分（经济/标准/快速）
   *    满分 10 分，时效越短分越高
   * ============================================================ */
  function initTimeChart() {
    var dom = document.getElementById('chart-time');
    if (!dom) return;
    var chart = echarts.init(dom);

    /* 时效天数 → 评分映射（越短越高）*/
    var indicator = [
      { name: '经济渠道时效', max: 10 },
      { name: '标准渠道时效', max: 10 },
      { name: '快速渠道时效', max: 10 }
    ];

    var scores = [
      { name: '递四方(4PX)',     value: [7, 9, 9] },
      { name: '云途(YunExpress)', value: [8, 9, 9] },
      { name: '燕文(Yanwen)',     value: [6, 7, 8] },
      { name: '万邑通(Winit)',    value: [7, 8, 8] },
      { name: '九方通逊',         value: [7, 9, 9] }
    ];

    var series = COMPANIES.map(function (name, i) {
      return {
        value: scores[i].value,
        name: name,
        lineStyle: { color: PALETTE[i], width: 2 },
        itemStyle: { color: PALETTE[i] },
        areaStyle: { color: PALETTE[i], opacity: 0.08 }
      };
    });

    chart.setOption({
      animation: false,
      tooltip: {
        trigger: 'item',
        formatter: function (p) {
          var s = '<b>' + p.name + '</b><br/>';
          indicator.forEach(function (ind, j) {
            s += ind.name + ': ' + p.value[j] + ' 分<br/>';
          });
          return s;
        }
      },
      legend: {
        bottom: 0,
        textStyle: { color: muted, fontSize: 12, fontFamily: 'InstrumentSans' }
      },
      radar: {
        indicator: indicator,
        shape: 'polygon',
        radius: '60%',
        axisName: { color: ink, fontSize: 12, fontFamily: 'InstrumentSans' },
        splitLine: { lineStyle: { color: rule } },
        splitArea: { show: true, areaStyle: { color: ['rgba(255,255,255,0)', 'rgba(255,255,255,0.05)'] } },
        axisLine: { lineStyle: { color: rule } }
      },
      series: [{
        type: 'radar',
        data: series
      }]
    });

    window.addEventListener('resize', function () { chart.resize(); });
  }

  /* ============================================================
   * 3. chart-radar — 五维综合评分雷达图
   *    价格 / 时效 / 覆盖 / 服务 / 技术，九方通逊突出
   * ============================================================ */
  function initRadarChart() {
    var dom = document.getElementById('chart-radar');
    if (!dom) return;
    var chart = echarts.init(dom);

    var indicator = [
      { name: '价格竞争力', max: 10 },
      { name: '时效稳定性', max: 10 },
      { name: '市场覆盖度', max: 10 },
      { name: '增值服务',   max: 10 },
      { name: '技术能力',   max: 10 }
    ];

    var scores = [
      { name: '九方通逊', value: [7, 9, 8, 9, 8] },
      { name: '递四方(4PX)',    value: [6, 8, 9, 8, 7] },
      { name: '云途(YunExpress)', value: [9, 8, 7, 7, 9] },
      { name: '燕文(Yanwen)',    value: [10, 6, 7, 6, 5] },
      { name: '万邑通(Winit)',   value: [7, 7, 8, 8, 8] }
    ];

    /* 九方通逊放在第一个，其余放后面 */
    var sortedSeries = [0, 1, 2, 3, 4].map(function (idx) {
      var isJF = idx === 0;
      return {
        value: scores[idx].value,
        name: scores[idx].name,
        lineStyle: {
          color: PALETTE[isJF ? 4 : idx],
          width: isJF ? 3 : 1.5
        },
        itemStyle: { color: PALETTE[isJF ? 4 : idx] },
        areaStyle: {
          color: PALETTE[isJF ? 4 : idx],
          opacity: isJF ? 0.2 : 0.06
        },
        symbol: isJF ? 'circle' : 'circle',
        symbolSize: isJF ? 8 : 5
      };
    });

    chart.setOption({
      animation: false,
      tooltip: {
        trigger: 'item',
        formatter: function (p) {
          var s = '<b>' + p.name + '</b><br/>';
          indicator.forEach(function (ind, j) {
            s += ind.name + ': ' + p.value[j] + ' / 10<br/>';
          });
          return s;
        }
      },
      legend: {
        bottom: 0,
        textStyle: { color: muted, fontSize: 12, fontFamily: 'InstrumentSans' }
      },
      radar: {
        indicator: indicator,
        shape: 'polygon',
        radius: '58%',
        center: ['50%', '48%'],
        axisName: { color: ink, fontSize: 13, fontFamily: 'InstrumentSans', fontWeight: 'bold' },
        splitLine: { lineStyle: { color: rule } },
        splitArea: { show: true, areaStyle: { color: ['rgba(255,255,255,0)', 'rgba(255,255,255,0.04)'] } },
        axisLine: { lineStyle: { color: rule } }
      },
      series: [{
        type: 'radar',
        data: sortedSeries
      }]
    });

    window.addEventListener('resize', function () { chart.resize(); });
  }

  /* ============================================================
   * 初始化所有图表
   * ============================================================ */
  function initAll() {
    initPriceChart();
    initTimeChart();
    initRadarChart();
  }

  /* DOM 就绪后初始化 */
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initAll);
  } else {
    initAll();
  }
})();
